// 状态实体化 · v1
// 第二阶段核心脚本：把 MVU 的 stat_data 渲染成实体状态文本，动态写回世界书条目「变量列表」（uid51）。
//
// 设计口径（与主人 2026-10-08 对齐）：
//   1. 落点复用 uid51（不新建条目，避免两条常亮条目互相矛盾）
//   2. 含分钟、内容变才写（状态永远新鲜；判据 4 重定义为「同内容不写 + 同轮多次触发只写一次」）
//   3. 写回用 render:'none'，不刷新世界书编辑器
//   4. VARIABLE_UPDATE_ENDED 之外再挂 VARIABLE_INITIALIZED，消除跨对话污染
//
// 渲染格式与本脚本的权威基准：第一阶段落地的 uid51 静态文本（558 字符 / 1419 字节），
// 已用原型逐字核对：由 initvar.yaml 渲染的结果与运行时 uid51 完全一致。渲染格式不得随意改动。

$(() => {
  const 世界书兜底名 = '星晚的自缚露出';
  const 条目名 = '变量列表';
  const 部位顺序 = ['头部', '面部', '上衣', '下装', '腿部', '脚部', '胸罩', '内裤'];

  // 探针：写回时在状态块之后附一行 WB_WRITE_PROBE_<ISO 时间戳>，用于验证第二阶段判据 2（跨轮可见）。
  // 判据 2 已于 2026-10-08 实测通过（第 1 轮的写入出现在第 2 轮 prompt_snapshot 的 uid51 里），故关闭。
  // 以后要复查跨轮可见性，把这里改回 true 重新构建推送即可。
  const 探针 = false;

  // 只有「非空且非无」的值才算有意义，避免空对象渲染成 [object Object]
  function 有意义(值: unknown): boolean {
    if (值 === null || 值 === undefined || 值 === '' || 值 === '无') return false;
    if (typeof 值 === 'object') return Object.keys(值 as object).length > 0;
    return true;
  }

  // 束缚/锁具这类「键=值」映射的渲染：全空则「无」，否则用「 / 」连接
  function 键值行(对象: unknown): string {
    if (!对象 || typeof 对象 !== 'object') return '无';
    const 项 = Object.entries(对象 as Record<string, unknown>)
      .filter(([, v]) => 有意义(v))
      .map(([k, v]) => `${k}=${typeof v === 'object' ? JSON.stringify(v) : String(v)}`);
    return 项.length ? 项.join(' / ') : '无';
  }

  function 补零(值: unknown): string {
    const 文本 = String(值 ?? '');
    return /^\d+$/.test(文本) ? 文本.padStart(2, '0') : 文本;
  }

  function 数量(值: unknown): unknown {
    if (值 && typeof 值 === 'object' && (值 as Record<string, unknown>)['数量'] != null) {
      return (值 as Record<string, unknown>)['数量'];
    }
    return 1;
  }

  function 渲染状态(stat_data: Record<string, any> | undefined | null): string | undefined {
    if (!stat_data || typeof stat_data !== 'object') return undefined;

    const 时间 = stat_data['时间'] ?? {};
    const 位置 = stat_data['位置'] ?? {};
    const 穿着 = stat_data['穿着'] ?? {};
    const 衣柜 = stat_data['$衣柜'] ?? {};
    const 道具库存 = stat_data['$道具库存'] ?? {};
    const 携带 = stat_data['当前携带'] ?? [];
    const 衣柜名 = Object.keys(衣柜);
    const 道具项 = Object.entries(道具库存);

    return [
      '---',
      '<status_current_variable>',
      `时间: ${时间['周几'] ?? ''} ${补零(时间['小时'])}:${补零(时间['分钟'])}`,
      `位置: ${位置['区域'] ?? ''}·${位置['地点'] ?? ''}`,
      `穿着: ${部位顺序.map(部位 => `${部位}=${穿着[部位] ?? '无'}`).join(' ')}`,
      `束缚: ${键值行(stat_data['束缚'])}`,
      `锁具: ${键值行(stat_data['锁具'])}`,
      `性欲值: ${stat_data['性欲值'] ?? ''}`,
      `心情: ${stat_data['心情'] ?? ''}`,
      `当前携带: ${Array.isArray(携带) && 携带.length ? 携带.join('、') : '无'}`,
      `露出经验: ${stat_data['露出经验'] ?? 0}`,
      '',
      '【衣柜·衣物与袜鞋只能逐字取自本清单，清单外的名字一律不得使用】',
      衣柜名.length ? 衣柜名.join('、') : '（空）',
      '',
      '【道具库存·玩具与拘束具只能逐字取自本清单，清单外的名字一律不得使用】',
      道具项.length ? 道具项.map(([k, v]) => `${k}×${数量(v)}`).join('、') : '（空）',
      '',
      '以上为封闭清单：正文与补丁中出现清单之外的衣物或道具，均属错误。',
      '</status_current_variable>',
      '',
    ].join('\n');
  }

  // 剥掉上一次写入留下的探针行，用于「内容没变就不写」的比对
  function 去探针(文本: string): string {
    const 位置 = 文本.indexOf('WB_WRITE_PROBE_');
    if (位置 < 0) return 文本;
    return 文本.slice(0, 位置).replace(/\n+$/, '\n');
  }

  function 取世界书名(): string | undefined {
    try {
      if (typeof getCharWorldbookNames === 'function') {
        const 绑定 = getCharWorldbookNames('current');
        if (绑定?.primary) return 绑定.primary;
      }
    } catch {
      /* 落到兜底名 */
    }
    return 世界书兜底名;
  }

  async function 同步(变量: { stat_data?: Record<string, any> } | undefined): Promise<void> {
    if (typeof getWorldbook !== 'function' || typeof updateWorldbookWith !== 'function') {
      console.warn('[状态实体化] 酒馆助手世界书 API 不可用，本轮跳过写回');
      return;
    }

    const stat_data = 变量?.stat_data;
    const 正文 = 渲染状态(stat_data);
    if (!正文) {
      console.warn('[状态实体化] 拿不到 stat_data，保留上次文本');
      return;
    }

    try {
      const 名 = 取世界书名();
      if (!名) return;

      const 世界书 = await getWorldbook(名);
      const 现条目 = 世界书.find(条目 => 条目.name === 条目名);
      if (!现条目) {
        console.warn(`[状态实体化] 在「${名}」里找不到条目「${条目名}」，本轮跳过`);
        return;
      }

      // 内容没变就不写：避免每轮重复落盘与编辑器抖动
      if (去探针(现条目.content ?? '') === 正文) return;

      const 落盘文本 = 探针 ? 正文 + `WB_WRITE_PROBE_${new Date().toISOString()}\n` : 正文;

      // 注：`render: 'none'` 不在 @types 的 `ReplaceWorldbookOptions`（只声明了 debounced|immediate）里，
      // 但实现（JS-Slash-Runner src/function/worldbook.ts）的 switch 没有 default 分支，
      // 传 'none' 即等于「不刷新世界书编辑器」—— 正是本脚本要的。
      const 选项 = { render: 'none' } as unknown as Parameters<typeof updateWorldbookWith>[2];

      await updateWorldbookWith(
        名,
        世界书条目 => 世界书条目.map(条目 => (条目.name === 条目名 ? { ...条目, content: 落盘文本 } : 条目)),
        选项,
      );
    } catch (错误) {
      // 写回失败不影响剧情推进：保留上次文本，下一轮再试
      console.warn('[状态实体化] 写回世界书失败，保留上次文本：', 错误);
    }
  }

  // 串行化：同一轮里 VARIABLE_UPDATE_ENDED 与 VARIABLE_INITIALIZED 可能都触发，
  // 排队执行可以保证后一次比对看到前一次的结果，从而不会重复写盘
  let 队列: Promise<void> = Promise.resolve();
  function 排入(任务: () => Promise<void>): void {
    队列 = 队列.then(任务).catch(错误 => console.warn('[状态实体化] 队列执行异常：', 错误));
  }

  waitGlobalInitialized('Mvu').then(() => {
    eventOn(Mvu.events.VARIABLE_UPDATE_ENDED, 变量 => {
      排入(() => 同步(变量));
    });

    // 新对话 / 变量重初始化：立刻用当前 stat_data 重渲染，消除「上一条对话的旧状态」
    if (Mvu.events.VARIABLE_INITIALIZED) {
      eventOn(Mvu.events.VARIABLE_INITIALIZED, 变量 => {
        排入(() => 同步(变量));
      });
    }
  });
});
